// =============================================================================
// MSHRCtl.sv —— CoupledL2（tl2chi）一个 slice 的 MSHR 资源池：16 个 MSHR + 4 个仲裁器 + SourceB
//
// 位置：L2 slice 内，夹在 MainPipe（分配 MSHR）、RequestArb（接收 MSHR 发起的 MainPipe 任务）
// 与 CHI 各通道（TXREQ / TXRSP / RXRSP / RXDAT）、上层 B 通道（SourceB）之间。
// 对照 Scala：coupledL2/src/main/scala/coupledL2/tl2chi/MSHRCtl.scala（约 260 行）。
//
// 结构（从上到下）：
//   · 16 份 MSHR（mshrs[i].entry），每份是一条事务的状态机（见 MSHR.sv）；
//   · 选择器 mshrSelector：挑最低编号的空闲 MSHR，MainPipe s3 要分配时用它；
//   · 四个 16 路 FastArbiter：各 MSHR 的 TXREQ / TXRSP / Probe / MainPipe 任务各自轮转仲裁出一路；
//   · SourceB：Probe 缓冲（等同地址的 Grant 收到 GrantAck 才放行）。
//   本层自己的"真逻辑"只有：占用计数（反压 ReqArb）、分配、把回来的响应按 mshrId / 地址
//   分发给对应 MSHR、releaseBuf 写 ID、嵌套写回数据 ID、L2 miss 与性能计数（§1-§5，手写）。
//   其余一万多行是扁平连线，由 scripts/gen_mshrctl.py 从 golden 端口表生成（GENERATED 区）。
//
// ★忠实 golden 的几处（照抄，勿"优化"）★
//   · MSHRSelector 只有 io_idle_0..14：第 15 个 MSHR 的 idle 在 golden 里被折掉了（选择器输出
//     的最高位与 idle_15 无关——ParallelPriorityMux 的最后一项是缺省值）。
//   · timers_i（64 位）只喂 XSPerfHistogram、REG 只喂一条断言：综合视图里都没有读者，
//     golden 保留，这里照写（两侧对称死位，FM 走 vmucp）。
//   · 性能事件 l2_cache_long_miss 是 16 个 4 位量相加、截断到 4 位（16 个同时成立会回绕成 0）。
//
// BEGIN GENERATED(nav) —— scripts/gen_mshrctl.py 生成
// 本文件导航：
//   L1285 BEGIN GENERATED(ms_entries)
//   L2352 §1 占用计数与反压（MSHRCtl.scala:107-111, 164-168）
//   L2368 §2 分配与响应分发（MSHRCtl.scala:114-161）
//   L2403 §3 releaseBuf 写 ID 与嵌套写回数据 ID（MSHRCtl.scala:181-191）
//   L2416 §4 L2 miss（给 TopDown）：有 MSHR 在处理 A 通道的 CPU 读/写数据请求（MSHRCtl.scala:117-1
//   L2428 §5 性能计数（MSHRCtl.scala:208-269）与断言影子
//   L2480 BEGIN GENERATED(children)
//   L4346 BEGIN GENERATED(wrapper)
